import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the CUDA kernel for matrix multiplication with shared memory and loop unrolling
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 32
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (N + BLOCK_SIZE - 1) / BLOCK_SIZE; t++) {
        // Load tile of A into shared memory
        int t_col = t * BLOCK_SIZE + threadIdx.x;
        if (row < N && t_col < N) {
            As[threadIdx.y][threadIdx.x] = A[row * N + t_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory
        int t_row = t * BLOCK_SIZE + threadIdx.y;
        if (t_row < N && col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[t_row * N + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Wait for all threads to load tiles
        __syncthreads();

        // Compute partial sum with loop unrolling
        for (int k = 0; k < BLOCK_SIZE; k += UNROLL_FACTOR) {
            sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
            sum += As[threadIdx.y][k+1] * Bs[k+1][threadIdx.x];
            sum += As[threadIdx.y][k+2] * Bs[k+2][threadIdx.x];
            sum += As[threadIdx.y][k+3] * Bs[k+3][threadIdx.x];
        }

        // Wait for all threads to compute
        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Check input dimensions
    TORCH_CHECK(A.dim() == 2, "A must be 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be 2D tensor");
    TORCH_CHECK(A.size(0) == B.size(0), "Matrices must be square and same size");
    TORCH_CHECK(A.size(1) == B.size(1), "Matrices must be square and same size");

    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    // Configure kernel launch parameters
    const int block_size = BLOCK_SIZE;
    dim3 threads(block_size, block_size);
    dim3 blocks((N + block_size - 1) / block_size, (N + block_size - 1) / block_size);

    // Launch kernel
    matmul_kernel<<<blocks, threads>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

# C++ wrapper declaration
matmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

# Load the CUDA extension
matmul_extension = load_inline(
    name="matmul_extension",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_ldflags=["-lcudart"]
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return matmul_extension.matmul_cuda(A, B)"}

